class APIClient{constructor(t){this.auth=t,this.baseURL=window.location.origin}async request(t,s={}){const e=`${this.baseURL}/api/v1${t}`,r={"Content-Type":"application/json",...s.headers},a=this.auth.getToken();a&&(r.Authorization=`Bearer ${a}`);try{const t=await fetch(e,{...s,headers:r});if(!t.ok){const s=await t.json().catch((()=>({detail:`HTTP ${t.status}: ${t.statusText}`})));throw new APIError(t.status,s.detail||s.message)}return 204===t.status?null:await t.json()}catch(t){if(t instanceof APIError)throw t;throw new APIError(0,`Network error: ${t.message}`)}}async get(t,s={}){const e=t.replace(/^\/api\/v1/,""),r=new URLSearchParams(s).toString(),a=r?`${e}?${r}`:e;return this.request(a)}async listFacts(t={}){const s=new URLSearchParams(t).toString();return this.request(`/facts?${s}`)}async createFact(t){return this.request("/facts",{method:"POST",body:JSON.stringify(t)})}async updateFact(t,s){return this.request(`/facts/${t}`,{method:"PUT",body:JSON.stringify(s)})}async deleteFact(t){return this.request(`/facts/${t}`,{method:"DELETE"})}async listArticles(t={}){const s=new URLSearchParams(t).toString();return this.request(`/articles?${s}`)}async getStatsSummary(t){return this.request(`/stats/summary?period=${t}`)}async getStatsByCategory(t,s){return this.request(`/stats/by-category?period=${t}&type=${s}`)}async getStatsByDay(t){return this.request(`/stats/by-day?period=${t}`)}}class APIError extends Error{constructor(t,s){super(s),this.name="APIError",this.status=t,this.detail=s}}